// F009 T000 — regenerates `v02-schema-v10.sql` from the frozen source commit
// `5ef5055` (v0.2 release, schema v10). Run from the repo root:
//
//   node server/tests/fixtures/generate-v02-schema-snapshot.mjs
//
// The contract (docs/features/0.3/F009-v344-frontend-foundation-migration/
// v02-fixture-contract.md) pins the snapshot to that commit's v1–v10
// migrations. `f009-v02-fixture.test.ts` fingerprints the committed snapshot,
// so any manual edit fails CI; rerun this script and re-audit the diff
// instead of editing the SQL by hand.

import { execSync } from "node:child_process";
import { writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const SOURCE_COMMIT = "5ef5055df20e3c61888082f3f11b43fe11e8467e";
const SOURCE_COMMIT_SHORT = "5ef5055";
const SCHEMA_VERSION = 10;
// Fixed applied_at so the generated bytes only change when the source DDL
// changes — never with the wall clock or the generating machine.
const APPLIED_AT = "2026-08-09T12:26:55.000Z";

const repoRoot = join(dirname(fileURLToPath(import.meta.url)), "..", "..", "..");

function extractSchema(commit, version) {
  const file = `server/src/db/schema-v${version}.ts`;
  const source = execSync(`git show ${commit}:${file}`, {
    cwd: repoRoot,
    encoding: "utf8",
    maxBuffer: 10 * 1024 * 1024,
  });
  const start = source.indexOf("`");
  const end = source.lastIndexOf("`");
  if (start === -1 || end === start) {
    throw new Error(`${file} at ${commit} does not contain a template literal`);
  }
  return source.slice(start + 1, end);
}

const parts = [
  `-- PersonaHub v0.2 release schema (v10), extracted from source commit`,
  `-- ${SOURCE_COMMIT_SHORT} (${SOURCE_COMMIT}) by`,
  `-- server/tests/fixtures/generate-v02-schema-snapshot.mjs. Do not edit by hand:`,
  `-- fingerprinted by server/tests/integration/f009-v02-fixture.test.ts.`,
  ``,
];

let schemaDdl = "";
for (let version = 1; version <= SCHEMA_VERSION; version += 1) {
  parts.push(`-- ================= schema v${version} =================`);
  parts.push(extractSchema(SOURCE_COMMIT, version));
  schemaDdl += `${parts.at(-1)}\n`;
}

parts.push(
  `-- ================= schema_version bookkeeping =================`,
  `-- applyMigrations() owns this table in live databases; the snapshot pins`,
  `-- the recorded chain at 1..${SCHEMA_VERSION} so the file is a complete v${SCHEMA_VERSION} database.`,
  `CREATE TABLE schema_version (`,
  `  version INTEGER PRIMARY KEY,`,
  `  applied_at TEXT NOT NULL`,
  `);`,
);

for (let version = 1; version <= SCHEMA_VERSION; version += 1) {
  parts.push(
    `INSERT INTO schema_version (version, applied_at) VALUES (${version}, '${APPLIED_AT}');`,
  );
}

const outPath = join(repoRoot, "server", "tests", "fixtures", "v02-schema-v10.sql");
writeFileSync(outPath, `${parts.join("\n")}\n`);
console.log(`wrote ${outPath} (${schemaDdl.split("\n").length} DDL lines from v1..v${SCHEMA_VERSION})`);
